-- 다섯을 다 건다

@Slf4j
@Aspect
@Component
@Order(0)
public class KindsAspect {

    @Pointcut("execution(* study.adv.app.OrderServiceV3.orderItem(..))")
    private void target() {}

    @Before("target()")
    public void before(JoinPoint jp) { log.info("before   {}", jp.getSignature().toShortString()); }

    @AfterReturning(pointcut = "target()", returning = "ret")
    public void ret(JoinPoint jp, Object ret) { log.info("return   {}", ret); }

    @AfterThrowing(pointcut = "target()", throwing = "e")
    public void thrown(JoinPoint jp, Exception e) { log.info("throw    {}", e.getClass().getSimpleName()); }

    @After("target()")
    public void after(JoinPoint jp) { log.info("after    {}", jp.getSignature().toShortString()); }

    @Around("target()")
    public Object around(ProceedingJoinPoint jp) throws Throwable {
        log.info("around 들어감");
        try { return jp.proceed(); }
        finally { log.info("around 나옴"); }
    }
}

