-- 인자도 바꾼다

@Around("target()")
public Object around(ProceedingJoinPoint jp) throws Throwable {
    Object[] args = jp.getArgs();
    log.info("원래 인자 {}", Arrays.toString(args));
    args[0] = ((String) args[0]).trim();
    return jp.proceed(args);
}

