-- 여러 번 부른다

@Around("target()")
public Object retry(ProceedingJoinPoint jp) throws Throwable {
    for (int i = 1; i <= 3; i++) {
        try { return jp.proceed(); }
        catch (Exception e) { log.warn("{} 번째 실패 {}", i, e.getClass().getSimpleName()); }
    }
    throw new IllegalStateException("3 번 실패");
}

