@Before("target()")
public void begin(JoinPoint jp) { trace.begin(jp.getSignature().toShortString()); }

@AfterReturning("target()")
public void end(JoinPoint jp) { trace.end(status.get()); }

@AfterThrowing(pointcut = "target()", throwing = "e")
public void fail(JoinPoint jp, Exception e) { trace.exception(status.get(), e); }

